# neighbor.py：隔壁组的“助手”。它不是 Agent，就是上一章那条画好的路。同一个服务，它也接得上
import json, re, sys
from plug import Plug

def fixed(request, plug):
    name = re.search(r"\w+\.md", request).group()
    found = json.loads(plug.call("search_docs", {"query": request}))
    if not found["source"]:
        return "查不到依据，没有存。"
    return plug.call("save_file", {"name": name, "content": f"{found['answer']}\n\n依据：{found['source']}"})

if __name__ == "__main__":
    plug = Plug("docs_server.py")
    for request in ["会议室一次最多订多久？存成 room.md。", "食堂几点开门？存成 canteen.md。"]:
        print(request, "→", fixed(request, plug))
    plug.close()

